// GET /api/products/search?name=lamp
// rateLimiter.allow(userId) and db.query(sql, params) are both async.
app.get('/api/products/search', requireLogin, async (req, res) => {
  const name = req.query.name || '';

  if (!rateLimiter.allow(req.user.id)) {
    return res.status(429).json({ error: 'Too many searches, try again later' });
  }

  const products = await db.query(
    "SELECT id, name, price_cents FROM products WHERE name ILIKE '%" + name + "%'"
  );

  const results = [];
  for (const p of products.rows) {
    const stock = await db.query(
      'SELECT SUM(quantity) AS qty FROM stock WHERE product_id = $1',
      [p.id]
    );
    results.push({ ...p, inStock: Number(stock.rows[0].qty) > 0 });
  }

  res.json(results);
});

// POST /api/wallet/transfer   body: { toUserId, amount }
// wallets.balance is a FLOAT column (dollars). One wallet row per user.
// db.query() runs each statement on its own (auto-commit).
app.post('/api/wallet/transfer', requireLogin, async (req, res) => {
  const fromId = req.user.id;
  const toId = req.body.toUserId;
  const amount = parseFloat(req.body.amount);

  const sender = await db.query(
    'SELECT balance FROM wallets WHERE user_id = $1', [fromId]);
  const balance = sender.rows[0].balance;

  if (balance < amount) {
    return res.status(400).json({ error: 'Insufficient funds' });
  }

  await db.query('UPDATE wallets SET balance = $1 WHERE user_id = $2',
    [balance - amount, fromId]);

  const receiver = await db.query(
    'SELECT balance FROM wallets WHERE user_id = $1', [toId]);
  await db.query('UPDATE wallets SET balance = $1 WHERE user_id = $2',
    [receiver.rows[0].balance + amount, toId]);

  res.json({ ok: true, newBalance: balance - amount });
});

