@require_login
def transfer():
    from_id = g.user.id
    to_id = request.json["to_user_id"]
    amount = float(request.json["amount"])

    sender = db.query_one("SELECT balance FROM wallets WHERE user_id = %s", (from_id,))
    balance = sender["balance"]

    if balance < amount:
        return jsonify(error="Insufficient funds"), 400

    db.execute("UPDATE wallets SET balance = %s WHERE user_id = %s",
               (balance - amount, from_id))

    receiver = db.query_one("SELECT balance FROM wallets WHERE user_id = %s", (to_id,))
    db.execute("UPDATE wallets SET balance = %s WHERE user_id = %s",
               (receiver["balance"] + amount, to_id))

    return jsonify(ok=True, new_balance=balance - amount)

