// Queue worker: sends one approved payout to our partner bank.
// The queue runs the job again later if this function throws.
async function processPayout(job) {
  const payout = await db.payouts.findById(job.payoutId);

  for (let attempt = 1; attempt <= 3; attempt++) {
    try {
      const resp = await fetch(`${BANK_API}/transfers`, {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${process.env.BANK_API_KEY}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          account: payout.accountNumber,
          amountCents: payout.amountCents,
        }),
      });
      if (resp.ok) {
        await db.payouts.update(payout.id, { status: 'sent' });
        return;
      }
    } catch (err) {
      // network problem, try again
    }
  }
}

