// orders.created_at is stored in UTC. The shop and its staff are in New York.
const reportCache = {};

app.get('/api/reports/daily-sales', requireAdmin, async (req, res) => {
  const day = req.query.date || new Date().toISOString().slice(0, 10);

  if (reportCache[day]) {
    return res.json(reportCache[day]);
  }

  const start = new Date(`${day}T00:00:00`);
  const end = new Date(start.getTime() + 24 * 60 * 60 * 1000);

  const result = await db.query(
    'SELECT * FROM orders WHERE created_at >= $1 AND created_at < $2',
    [start, end]
  );

  let totalCents = 0;
  for (const order of result.rows) {
    totalCents += order.total_cents;
  }

  const report = { day, count: result.rows.length, totalCents, orders: result.rows };
  reportCache[day] = report;
  res.json(report);
});

