# GET /api/reports/daily-sales?date=2026-03-14   (admin dashboard)
# orders.created_at is stored in UTC. The shop and its staff are in New York.
report_cache = {}

@app.get("/api/reports/daily-sales")
@require_admin
def daily_sales():
    day = request.args.get("date") or datetime.now(timezone.utc).date().isoformat()

    if day in report_cache:
        return jsonify(report_cache[day])

    start = datetime.strptime(day, "%Y-%m-%d")
    end = start + timedelta(days=1)

    rows = db.query(
        "SELECT * FROM orders WHERE created_at >= %s AND created_at < %s",
        (start, end),
    )

    total_cents = 0
    for order in rows:
        total_cents += order["total_cents"]

    report = {"day": day, "count": len(rows), "total_cents": total_cents, "orders": rows}
    report_cache[day] = report
    return jsonify(report)

