// Runs every hour. Emails a reminder for each appointment in the next 24 hours.
// appointments.starts_at is a UTC timestamp. users.timezone is like 'Europe/Berlin'.
// Two copies of this worker run on different servers, for redundancy.
async function sendReminders() {
  const now = new Date();
  const in24h = new Date(now.getTime() + 24 * 60 * 60 * 1000);

  const { rows: appts } = await db.query(
    `SELECT * FROM appointments
     WHERE starts_at BETWEEN $1 AND $2 AND reminder_sent = false`,
    [now, in24h]
  );

  for (const appt of appts) {
    const { rows } = await db.query(
      'SELECT email, name, timezone FROM users WHERE id = $1', [appt.user_id]);
    const user = rows[0];
    const time = appt.starts_at.toISOString().slice(11, 16); // "14:30"

    try {
      await mailer.send(user.email, 'Appointment reminder',
        `Hi ${user.name}, see you at ${time}.`);
    } catch (err) {
      // the email service is sometimes flaky, skip
    }

    await db.query(
      'UPDATE appointments SET reminder_sent = true WHERE id = $1', [appt.id]);
  }
}

