    logger.info("Reset link for %s: %s", user["email"], link)
    mailer.send(user["email"], "Reset your password", link)
    return jsonify(ok=True)


@app.post("/api/password-reset/confirm")
def confirm_reset():
    row = db.query_one(
        "SELECT user_id FROM reset_tokens WHERE token = %s AND expires_at > now()",
        (request.json["token"],),
    )
    if row is None:
        return jsonify(error="Invalid or expired token"), 400

    hashed = bcrypt.hashpw(request.json["new_password"].encode(), bcrypt.gensalt(rounds=12))
    db.execute("UPDATE users SET password_hash = %s WHERE id = %s", (hashed.decode(), row["user_id"]))
    return jsonify(ok=True)

