// Webhook called by our payment provider when a payment changes state.
// The provider retries a delivery if it does not get a 2xx response within 10 seconds.
// db.transaction(fn) runs fn in one database transaction: everything commits, or nothing.
app.post('/webhooks/payments', express.json(), async (req, res) => {
  const event = req.body;

  try {
    if (event.type === 'payment.succeeded') {
      const { orderId, userId, credits } = event.data.metadata;

      await db.transaction(async (tx) => {
        await tx.query("UPDATE orders SET status = 'paid' WHERE id = $1", [orderId]);
        await tx.query('UPDATE users SET credits = credits + $1 WHERE id = $2',
          [credits, userId]);
      });

      await fetch(`${EMAIL_API}/send`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ template: 'receipt', userId, orderId }),
      });
    }
  } catch (err) {
    console.error('webhook failed');
  }

  res.sendStatus(200);
});

