# Webhook called by our payment provider when a payment changes state.
# The provider retries a delivery if it does not get a 2xx response within 10 seconds.
# db.transaction() commits everything inside the block together, or nothing.
@app.post("/webhooks/payments")
def payment_webhook():
    event = request.get_json()

    try:
        if event["type"] == "payment.succeeded":
            meta = event["data"]["metadata"]

            with db.transaction():
                db.execute("UPDATE orders SET status = 'paid' WHERE id = %s", (meta["order_id"],))
                db.execute("UPDATE users SET credits = credits + %s WHERE id = %s",
                           (meta["credits"], meta["user_id"]))

            requests.post(f"{EMAIL_API}/send", json={
                "template": "receipt",
                "user_id": meta["user_id"],
                "order_id": meta["order_id"],
            })
    except Exception:
        logger.error("webhook failed")

    return "", 200
